<template><WorkspaceLayout role="WORKER"><p class="eyebrow">工作台</p><div class="heading"><div><h1 class="page-title">今天的服务安排</h1><p class="muted">任务操作均以当前有效派单为准。</p></div><el-switch v-model="accepting" active-text="接单中" inactive-text="暂停接单" @change="toggle" /></div><p v-if="error" class="form-error" role="alert">{{ error }}</p><div class="stats"><div class="surface stat"><strong>{{ dashboard?.pending ?? '—' }}</strong><span>待接单</span></div><div class="surface stat"><strong>{{ dashboard?.active ?? '—' }}</strong><span>进行中任务</span></div></div><section class="surface tasks"><h2>当前任务</h2><article v-for="task in tasks" :key="task.order_id" class="task"><div><span class="eyebrow">#{{ task.order_id }} · {{ statusName(task.status) }}</span><h3>{{ task.item_name_snapshot }}</h3><p class="muted">{{ formatTime(task.start_at) }} 至 {{ formatTime(task.end_at) }}</p></div><div class="actions"><button class="text-button" @click="showTask(task.order_id)">查看详情</button><button v-if="task.status==='WAITING_ACCEPTANCE'" class="primary" @click="act(task.order_id,'accept')">接单</button><button v-if="task.status==='WAITING_ACCEPTANCE'" class="text-button" @click="reject(task.order_id)">拒单</button><button v-if="task.status==='WAITING_SERVICE'" class="primary" @click="act(task.order_id,'start')">开始服务</button><button v-if="task.status==='IN_SERVICE'" class="primary" @click="act(task.order_id,'submit-completion')">提交完成</button><button v-if="task.status==='IN_SERVICE'" class="text-button" @click="interrupt(task.order_id)">上报中断</button></div></article><div v-if="!tasks.length && !error" class="empty">当前暂无有效任务。</div></section><section class="surface tasks leave"><div class="heading"><h2>请假申请</h2><button class="text-button" @click="leaveOpen=true">申请请假</button></div><div v-for="leave in leaves" :key="leave.id" class="task"><span>{{ formatTime(leave.start_at) }} 至 {{ formatTime(leave.end_at) }}</span><strong>{{ leaveStatus(leave.status) }}</strong></div><div v-if="!leaves.length" class="empty">暂无请假记录。</div></section><el-dialog v-model="leaveOpen" title="申请请假" width="min(94vw, 520px)"><el-form label-position="top"><el-form-item label="开始时间"><el-input v-model="leaveForm.startAt" type="datetime-local" /></el-form-item><el-form-item label="结束时间"><el-input v-model="leaveForm.endAt" type="datetime-local" /></el-form-item><el-form-item label="原因"><el-input v-model="leaveForm.reason" type="textarea" maxlength="300" /></el-form-item></el-form><template #footer><button class="primary" @click="requestLeave">提交申请</button></template></el-dialog><el-dialog v-model="detailOpen" title="任务详情" width="min(94vw, 600px)"><div v-if="taskDetail" class="task-detail"><p><strong>服务对象</strong>{{ taskDetail.elder_name }}</p><p><strong>服务项目</strong>{{ taskDetail.item_name_snapshot }}</p><p><strong>时间</strong>{{ formatTime(taskDetail.start_at) }} 至 {{ formatTime(taskDetail.end_at) }}</p><p><strong>地点</strong>{{ taskDetail.street_name_snapshot }} {{ taskDetail.address_snapshot }}</p><p><strong>规则</strong>{{ taskDetail.rule_snapshot }}</p><p><strong>状态</strong>{{ statusName(taskDetail.status) }}</p></div></el-dialog></WorkspaceLayout></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import WorkspaceLayout from '../../layouts/WorkspaceLayout.vue'
import { api } from '../../api/client'
type Task = {order_id:number; item_name_snapshot:string; start_at:string; end_at:string; status:string}
type TaskDetail = Task & {elder_name:string;category_snapshot:string;rule_snapshot:string;duration_minutes:number;street_name_snapshot:string;address_snapshot:string;assignment_status:string}
type Dashboard = {accepting:boolean;pending:number;active:number}
const dashboard=ref<Dashboard|null>(null),tasks=ref<Task[]>([]),accepting=ref(false),error=ref('')
const taskDetail=ref<TaskDetail|null>(null),detailOpen=ref(false)
type Leave={id:number;start_at:string;end_at:string;status:string}
const leaves=ref<Leave[]>([]),leaveOpen=ref(false),leaveForm=reactive({startAt:'',endAt:'',reason:''})
const labels:Record<string,string>={WAITING_ACCEPTANCE:'待接单',WAITING_SERVICE:'待服务',IN_SERVICE:'服务中',WAITING_CONFIRMATION:'待用户确认'}
function statusName(value:string){return labels[value]||value}
const leaveLabels:Record<string,string>={PENDING:'待审批',APPROVED:'已批准',REJECTED:'已拒绝'}
function leaveStatus(value:string){return leaveLabels[value]||value}
function formatTime(value:string){return new Date(value).toLocaleString('zh-CN',{hour12:false})}
async function load(){try{[dashboard.value,tasks.value,leaves.value]=await Promise.all([api<Dashboard>('/worker/dashboard'),api<Task[]>('/worker/tasks'),api<Leave[]>('/worker/leaves')]);accepting.value=dashboard.value.accepting;error.value=''}catch(reason){error.value=reason instanceof Error?reason.message:'任务加载失败'}}
async function toggle(){try{await api('/worker/accepting',{method:'POST',body:JSON.stringify({accepting:accepting.value})});ElMessage.success('接单状态已更新')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'操作失败');await load()}}
async function act(id:number,action:'accept'|'start'|'submit-completion'){try{await ElMessageBox.confirm(action==='submit-completion'?'确认已完成服务并提交给用户？':'确认执行该操作？','请确认');await api(`/orders/${id}/${action}`,{method:'POST'});await load();ElMessage.success('操作成功')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function reject(id:number){try{const result=await ElMessageBox.prompt('请填写拒单原因','拒绝派单',{inputValidator:value=>Boolean(value?.trim())||'必须填写原因'});await api(`/orders/${id}/reject`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});await load();ElMessage.success('已拒绝派单')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function interrupt(id:number){try{const result=await ElMessageBox.prompt('请说明服务中断原因，提交后将进入异常协调。','上报服务中断',{inputValidator:value=>Boolean(value?.trim())||'必须填写原因'});await api(`/orders/${id}/interrupt`,{method:'POST',body:JSON.stringify({reason:result.value.trim()})});await load();ElMessage.success('中断已上报')}catch(reason){if(reason instanceof Error)ElMessage.error(reason.message)}}
async function requestLeave(){if(!leaveForm.startAt||!leaveForm.endAt||!leaveForm.reason.trim()){ElMessage.error('请填写完整的请假信息');return}try{await api('/worker/leaves',{method:'POST',body:JSON.stringify(leaveForm)});leaveOpen.value=false;leaves.value=await api<Leave[]>('/worker/leaves');ElMessage.success('申请已提交')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'申请失败')}}
async function showTask(id:number){try{taskDetail.value=await api<TaskDetail>(`/worker/tasks/${id}`);detailOpen.value=true}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'任务详情加载失败')}}
onMounted(load)
</script>
<style scoped>.heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.stats{display:flex;gap:16px;margin:28px 0}.stat{padding:22px 30px;min-width:160px;display:grid;gap:6px}.stat strong{font-size:34px}.stat span{color:#678075}.tasks{padding:28px}.tasks h2{margin:0 0 8px}.task{display:flex;justify-content:space-between;align-items:center;gap:20px;border-top:1px solid #e9efea;padding:22px 0}.task h3{margin:8px 0}.task p{margin:0}.actions{display:flex;gap:10px;flex-wrap:wrap}.task-detail p{display:flex;gap:14px;border-bottom:1px solid #edf1ee;padding:10px 0}.task-detail strong{min-width:78px}.leave{margin-top:18px}.form-error{color:#b34939}@media(max-width:650px){.heading,.task{align-items:flex-start;flex-direction:column}}</style>
